import Pyro4
import os
import sys
import logging
import signal
import imp
import zipfile
import inspect
from functools import wraps
import shutil
import traceback
from feature_package import FeaturePackage


class Server(object):

    def get_server_pid(self):
        pid = os.getpid()
        logging.info("got server pid {}".format(pid))
        return pid

    def run_shell_command(self, command):
        with os.popen(command, "r") as f:
            return f.read()


class ServerRunner(object):
    def __init__(self, ip_address, port):
        self._ip_address = ip_address
        self._port = port
        self.daemon = None
        self._register_items = []
        self._register_class = None

    def register_expose_class(self, obj_or_class, objectid):
        self._register_items.append((obj_or_class, objectid))

    def start_pyro_daemon(self, success_with_uri_pid_message_template):
        Pyro4.config.SOCK_REUSE = True
        signal.signal(signal.SIGTERM, self.stop_pyro_daemon)

        with Pyro4.Daemon(host=self._ip_address, port=int(self._port)) as self.daemon:
            for item in self._register_items:
                uri = self.daemon.register(obj_or_class=item[0], objectId=item[1])
                logging.info(success_with_uri_pid_message_template.format(uri, os.getpid()))
            try:
                self.daemon.requestLoop()
            except BaseException as exp:
                logging.error("pyro server was stopped by unexpected reason {}".format(exp))
                self.stop_pyro_daemon()

    def stop_pyro_daemon(self):
        logging.info("Stopping pyro_server")
        self.daemon.shutdown()

    @staticmethod
    def config_log(log_name):
        format_report = '[%(asctime)s][%(filename)s][line:%(lineno)d] %(levelname)s %(message)s'
        logging.basicConfig(level=logging.DEBUG,
                            format=format_report,
                            filename=log_name,
                            filemode='w')


#  helper
def load_exposed_entry(feature_package):
    library_folder = feature_package.server_package_name
    search_folder = \
        library_folder.replace('.', '/') if library_folder != './' and library_folder != '.' else library_folder
    fn_, path, desc = imp.find_module(feature_package.exposed_module_name, [search_folder, ])
    mod = imp.load_module('customized_module', fn_, path, desc)
    customized_class = getattr(mod, feature_package.exposed_class_name)
    hook_with_server_class(customized_class)
    return customized_class


def hook_with_server_class(exposed_class_name):
    for member in dir(Server):
        if not member.startswith('_'):
            if sys.version[0:1] == '2':
                setattr(exposed_class_name, member, getattr(Server, member).__func__)
            elif sys.version[0:1] == '3':
                setattr(exposed_class_name, member, getattr(Server, member))
            else:
                pass


def log(func):
    @wraps(func)
    def wrapped(*args, **kwargs):
        try:
            logging.debug("Entering: [{}] with parameters {} {}".format(func.__name__, args, kwargs))
            try:
                output = func(*args, **kwargs)
                logging.debug("output from {}: {} ".format(func.__name__, output))
                return output
            except Exception as e:
                # logging.debug('Exception in {} : {}'.format(func.__name__, e))
                logging.debug("Exception {e} in {func}, stack is : {stack}".
                              format(e=e, func=func.__name__, stack=traceback.format_exc()))
                raise
        finally:
            logging.debug("Exiting: [{}]".format(func.__name__))
    return wrapped


def decorate_with_logging(cls):
    for name, m in inspect.getmembers(cls, lambda x: inspect.isfunction(x) or inspect.ismethod(x)):
        if not name.startswith('_'):
            setattr(cls, name, log(m))
    return cls


def _unzip_file(source_zip_file_path, target_folder):
    os.mkdir(target_folder)
    zip_file = zipfile.ZipFile(source_zip_file_path)
    zip_file.extractall(target_folder)
    zip_file.close()


def normalize_package(package_folder):
    parent_folder, folder_name = os.path.split(package_folder)
    if '.' in folder_name:
        sub_folder_names = folder_name.split('.')
        current_full_folder_path = parent_folder
        sub_folders = []
        for sub_folder_name in sub_folder_names:
            current_full_folder_path = current_full_folder_path + '/' + sub_folder_name
            sub_folders.append(current_full_folder_path)

        sub_folders_without_last_one = sub_folders[:-1]
        for sub_folder in sub_folders_without_last_one:
            sys.path.append(sub_folder)
            if not os.path.exists(sub_folder) or os.path.isfile(sub_folder):
                os.mkdir(sub_folder)
            package_file_path = sub_folder + '/__init__.py'
            init_file = open(package_file_path, mode="w")
            init_file.close()

        last_sub_folder = sub_folders[-1]
        sys.path.append(last_sub_folder)
        shutil.copytree(package_folder, last_sub_folder)
        shutil.rmtree(package_folder)
    else:
        init_file = open(package_folder + '/__init__.py', mode="w")
        init_file.close()
        sys.path.append(package_folder)


def unzip_all_packages(directory='./', except_paths=None):
    except_paths = except_paths or []
    file_names = os.listdir(directory)
    for file_name in file_names:
        source_file_path = directory + file_name

        if file_name.endswith('zip'):
            target_folder = os.path.splitext(source_file_path)[0]
            _unzip_file(source_file_path, target_folder)
            normalize_package(target_folder)
            os.remove(directory + file_name)
        elif os.path.isdir(source_file_path) and _not_in_paths(source_file_path, except_paths):
            normalize_package(source_file_path)
        else:
            pass


def _not_in_paths(test_path, paths):
    for path in paths:
        s1 = os.stat(test_path)
        s2 = os.stat(path)
        if s1.st_ino == s2.st_ino and s1.st_dev == s2.st_dev:
            return False
    return True


if __name__ == "__main__":  # noqa: C901
    server_ip_address = ""
    server_port = 8080
    success_message_template = ""
    log_name = ""

    feature_packages = []
    if len(sys.argv) == 9:  # deprecated argument list
        (server_ip_address, server_port, object_id, server_package_name, exposed_module_name,
         exposed_class_name, success_message_template, log_name) = sys.argv[1:]
        feature_packages.append(FeaturePackage.Remote(object_id=object_id,
                                                      server_package_name=server_package_name,
                                                      exposed_module_name=exposed_module_name,
                                                      exposed_class_name=exposed_class_name))

    elif len(sys.argv) == 6:
        (server_ip_address, server_port, packages_info, success_message_template, log_name) = sys.argv[1:]
        packages_info_list = eval(packages_info)
        feature_packages = [FeaturePackage.Remote.from_dict(package) for package in packages_info_list]

    else:
        raise Exception("input parameter invalid: {}".format(str(sys.argv)))

    unzip_all_packages(except_paths=[os.path.dirname(log_name), ])

    runner = ServerRunner(server_ip_address, server_port)
    runner.config_log(log_name)
    try:
        for package in feature_packages:
            exposed = load_exposed_entry(package)
            decorate_with_logging(exposed)
            Pyro4.expose(exposed)
            exposed_instance = None
            if package.exposed_class_init_kwargs:
                exposed_instance = exposed(**(package.exposed_class_init_kwargs))
            else:
                exposed_instance = exposed()
            runner.register_expose_class(exposed_instance, package.object_id)

        runner.start_pyro_daemon(success_message_template)
    except Exception as e:
        logging.error("Exception is {e} , stack is : {stack}".
                      format(e=e, stack=traceback.format_exc()))
        raise
